function merge(target,patch){for(const [key,value]of Object.entries(patch)){if(value&&typeof value==='object'&&!Array.isArray(value)){target[key]??={};merge(target[key],value);}else target[key]=value;}return target;}
for(const [file,patch]of Object.entries(patches)){let contents={};try{contents=JSON.parse(await readFile(new URL(file,locales),'utf8'));}catch{}await writeFile(new URL(file,locales),JSON.stringify(merge(contents,patch)));}
